{"code":"import { runSql } from '../servers/earnings/index.js';

// Calcular a média da margem líquida dos últimos 8 trimestres por empresa dos EUA
const result = await runSql({ sql: `
  SELECT 
    symbol,
    name,
    AVG(net_margin) as avg_net_margin
  FROM v_quarter
  WHERE market = 'EUA'
  GROUP BY symbol, name
  ORDER BY avg_net_margin DESC
  LIMIT 3
` });

