{"code":"import { runSql } from '../servers/earnings/index.js';

// Calcular a média da margem líquida dos últimos 8 trimestres para cada empresa dos EUA
const result = await runSql({ sql: `
    WITH us_companies AS (
        SELECT symbol, name FROM v_company WHERE market = 'EUA'
    ),
    ranked_quarters AS (
        SELECT 
            q.symbol,
            q.net_margin,
            ROW_NUMBER() OVER (PARTITION BY q.symbol ORDER BY q.period_end DESC) as rn
        FROM v_quarter q
        INNER JOIN us_companies uc ON q.symbol = uc.symbol
    ),
    avg_margins AS (
        SELECT 
            symbol,
            AVG(net_margin) as avg_net_margin
        FROM ranked_quarters
        WHERE rn <= 8
        GROUP BY symbol
    )
    SELECT 
        am.symbol,
        am.avg_net_margin
    FROM avg_margins am
    ORDER BY am.avg_net_margin DESC
    LIMIT 3
` });

console.log("Top 3 médias de margem líquida (EUA) - últimos 8 trimestres:");
result.rows.forEach((row, i) => {
    console.log(`${i+1}. ${row.symbol}: ${row.avg_net_margin.toFixed(2)}%`);
});
"}
